      id: `page-${index + 1}`,
      number: index + 1,
    }));
  }

  get length() {
    return this.pages.length;
  }

  getPage(index) {
    return this.pages[index] ?? null;
  }
}

class FlipbookState {
  constructor(totalPages) {
    this.totalPages = totalPages;
    this.currentLeft = 0;
    this.isAnimating = false;
  }

  get canGoNext() {
    return this.currentLeft + 2 < this.totalPages && !this.isAnimating;
  }

  get canGoPrev() {
    return this.currentLeft > 0 && !this.isAnimating;
  }

  commit(direction) {
    this.currentLeft += direction === "next" ? 2 : -2;
  }
}

class FlipbookRenderer {
  constructor(root, adapter, state, onAnimationDone) {
    this.root = root;
    this.adapter = adapter;
    this.state = state;
    this.onAnimationDone = onAnimationDone;
  }

  renderStaticSpread() {
    this.root.innerHTML = "";
    const spread = document.createElement("div");
    spread.className = "spread";
    spread.append(
      this.createPage(this.adapter.getPage(this.state.currentLeft), "left"),
      this.createPage(this.adapter.getPage(this.state.currentLeft + 1), "right"),
    );
    this.root.append(spread);
  }

  animate(direction) {
    const turningPage =
      direction === "next"
        ? this.adapter.getPage(this.state.currentLeft + 1)
        : this.adapter.getPage(this.state.currentLeft - 2);

    if (!turningPage) return;

    const page = this.createPage(turningPage, direction === "next" ? "right" : "left");
    page.classList.add("turning");
    if (direction === "prev") page.classList.add("reverse");

    this.root.append(page);
    requestAnimationFrame(() => {
      page.style.transform = direction === "next" ? "rotateY(-178deg)" : "rotateY(178deg)";
    });

    page.addEventListener(
      "transitionend",
      () => {
        this.onAnimationDone(direction);
        page.remove();
      },
      { once: true },
    );
  }

  createPage(page, side) {
    const element = document.createElement("article");
    element.className = `page ${side}`;

    if (!page) {
      element.setAttribute("aria-hidden", "true");
      return element;
    }

    element.style.setProperty("--page-color", page.color);
    element.innerHTML = `
      <div class="page-content">
        <span class="page-number">${String(page.number).padStart(2, "0")}</span>
        <div class="visual" role="img" aria-label="${page.title} visual"></div>
        <div>
          <h2 class="page-title">${page.title}</h2>
          <p class="page-copy">${page.copy}</p>
        </div>
      </div>
      <div class="shadow-pane"></div>
    `;
    return element;
  }
}

class FlipbookController {
  constructor({ root, previousButton, nextButton, status, progress }) {
    this.adapter = new ContentAdapter(rawPages);
    this.state = new FlipbookState(this.adapter.length);
    this.renderer = new FlipbookRenderer(root, this.adapter, this.state, (direction) => {
      this.state.commit(direction);
      this.state.isAnimating = false;
      this.renderer.renderStaticSpread();
      this.syncControls();
    });

    this.previousButton = previousButton;
    this.nextButton = nextButton;
    this.status = status;
    this.progress = progress;
    this.dragStartX = 0;

    this.bindEvents(root);
    this.renderer.renderStaticSpread();
    this.syncControls();
  }

  bindEvents(root) {
    this.nextButton.addEventListener("click", () => this.turn("next"));
    this.previousButton.addEventListener("click", () => this.turn("prev"));

    window.addEventListener("keydown", (event) => {
      if (event.key === "ArrowRight") this.turn("next");
      if (event.key === "ArrowLeft") this.turn("prev");
    });

    root.addEventListener("pointerdown", (event) => {
      this.dragStartX = event.clientX;
    });

    root.addEventListener("pointerup", (event) => {
      const distance = event.clientX - this.dragStartX;
      if (Math.abs(distance) < 45) return;
      this.turn(distance < 0 ? "next" : "prev");
    });
  }

  turn(direction) {
    const allowed = direction === "next" ? this.state.canGoNext : this.state.canGoPrev;
    if (!allowed) return;

    this.state.isAnimating = true;
    this.syncControls();
    this.renderer.animate(direction);
  }

  syncControls() {
    this.previousButton.disabled = !this.state.canGoPrev;
    this.nextButton.disabled = !this.state.canGoNext;

    const rightPage = Math.min(this.state.currentLeft + 2, this.adapter.length);
    this.status.value = `${this.state.currentLeft + 1}-${rightPage} / ${this.adapter.length}`;

    const progress = rightPage / this.adapter.length;
    this.progress.style.width = `${progress * 100}%`;
  }
}

new FlipbookController({
  root: document.querySelector("#book"),
  previousButton: document.querySelector("#prevBtn"),
  nextButton: document.querySelector("#nextBtn"),
  status: document.querySelector("#pageStatus"),
  progress: document.querySelector("#progressBar"),
});

