import SwiftUI
import UIKit
import WebKit

extension Notification.Name {
    static let flashPlayImmersiveModeChanged = Notification.Name("flashPlayImmersiveModeChanged")
}

struct FeedHomeView: View {
    @ObservedObject var store: FlashPlayStore

    @State private var currentIndex = 0
    @State private var dragOffset: CGFloat = 0
    @State private var sessionProgress = 0.0
    @State private var currentDemoSeed = UUID()
    @State private var isInfoPanelHidden = false
    @State private var isRoomMode = false
    @State private var wheelAccumulatedDelta: CGFloat = 0
    @State private var generatedBannerTitle: String?
    @State private var shareSheetURL: URL?

    private var copy: FlashPlayCopy {
        FlashPlayCopy(language: store.language)
    }

    private var currentGame: GameItem {
        store.featuredGames[min(max(currentIndex, 0), max(store.featuredGames.count - 1, 0))]
    }

    var body: some View {
        GeometryReader { proxy in
            let metrics = FeedLayoutMetrics(containerSize: proxy.size)

            ZStack {
                LinearGradient(colors: currentGame.background, startPoint: .topLeading, endPoint: .bottomTrailing)
                    .ignoresSafeArea()

                playableStage(metrics: metrics)
                    .ignoresSafeArea()

                VStack(spacing: 0) {
                    topBar(metrics: metrics)
                    Spacer()
                    bottomHUD(metrics: metrics)
                }
                .padding(.horizontal, metrics.horizontalPadding)
                .padding(.top, metrics.topPadding)
                .safeAreaPadding(.bottom, isInfoPanelHidden ? 10 : metrics.contentBottomInset)

                if let generatedBannerTitle {
                    generatedSuccessBanner(title: generatedBannerTitle)
                        .padding(.top, metrics.topPadding + 18)
                        .padding(.horizontal, metrics.horizontalPadding)
                        .transition(.move(edge: .top).combined(with: .opacity))
                }

                if let shareSheetURL {
                    shareLinkOverlay(url: shareSheetURL)
                        .transition(.opacity.combined(with: .scale(scale: 0.96)))
                }

                if isRoomMode {
                    roomCloseButton(metrics: metrics)
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        }
        .ignoresSafeArea()
        .animation(.spring(response: 0.35, dampingFraction: 0.86), value: currentIndex)
        .onAppear {
            exitRoomMode(animated: false)
            restartSessionProgress()
        }
        .onChange(of: currentIndex) { _, _ in
            currentDemoSeed = UUID()
            wheelAccumulatedDelta = 0
            exitRoomMode(animated: false)
            restartSessionProgress()
        }
        .onChange(of: store.pendingPlayGameID) { _, pendingID in
            guard let pendingID,
                  let targetIndex = store.featuredGames.firstIndex(where: { $0.id == pendingID })
            else { return }
            currentIndex = targetIndex
            currentDemoSeed = UUID()
            enterRoomMode(animated: false)
            if store.justGeneratedGameID == pendingID {
                let title = normalizedGameName(from: store.featuredGames[targetIndex].title)
                generatedBannerTitle = title
                store.justGeneratedGameID = nil
                Task {
                    try? await Task.sleep(for: .milliseconds(1500))
                    await MainActor.run {
                        withAnimation(.easeOut(duration: 0.22)) {
                            generatedBannerTitle = nil
                        }
                    }
                }
            }
            store.pendingPlayGameID = nil
            restartSessionProgress()
        }
        .onDisappear {
            wheelAccumulatedDelta = 0
            postImmersiveMode(hidden: false)
        }
    }

    private func topBar(metrics: FeedLayoutMetrics) -> some View {
        Color.clear
            .frame(height: 0)
    }

    private func playableStage(metrics: FeedLayoutMetrics) -> some View {
        ZStack {
            if currentGame.externalGameURL != nil {
                PlayableGameSurface(game: currentGame, seed: currentDemoSeed)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            } else {
                PlayableGameSurface(game: currentGame, seed: currentDemoSeed)
                    .padding(metrics.stagePadding)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
            }

            if !isRoomMode {
                feedPreviewInteractionLayer
            }
        }
        .background {
            if currentGame.externalGameURL == nil {
                Rectangle()
                    .fill(.ultraThinMaterial.opacity(0.35))
            } else {
                Color.clear
            }
        }
        .frame(maxWidth: .infinity)
        .frame(maxHeight: .infinity)
        .clipped()
        .scaleEffect(dragOffset == 0 ? 1 : 0.995)
        .offset(y: dragOffset * 0.15)
    }

    private var feedPreviewInteractionLayer: some View {
        Color.clear
            .contentShape(Rectangle())
            .onTapGesture {
                enterRoomMode()
            }
            .gesture(feedGesture)
            .overlay {
                WheelSwipeOverlay { delta in
                    wheelAccumulatedDelta += delta
                    if wheelAccumulatedDelta < -28 {
                        wheelAccumulatedDelta = 0
                        move(by: 1)
                    } else if wheelAccumulatedDelta > 28 {
                        wheelAccumulatedDelta = 0
                        move(by: -1)
                    }
                }
            }
    }

    @ViewBuilder
    private func bottomHUD(metrics: FeedLayoutMetrics) -> some View {
        if !isInfoPanelHidden {
            VStack(alignment: .leading, spacing: metrics.hudSpacing) {
                Spacer(minLength: 0)
                actionPairBar(metrics: metrics)
                navigationStrip(metrics: metrics)
            }
        }
    }

    private func actionPairBar(metrics: FeedLayoutMetrics) -> some View {
        HStack {
            Button {
                store.toggleSave(for: currentGame.id)
            } label: {
                actionRailLabel(
                    icon: currentGame.isSaved ? "star.fill" : "star",
                    isActive: currentGame.isSaved
                )
            }
            .buttonStyle(.plain)
            .frame(width: metrics.controlSize, alignment: .leading)

            Spacer(minLength: 0)

            if let shareURL = shareLibraryURL(for: currentGame) {
                Button {
                    shareSheetURL = shareURL
                } label: {
                    actionRailLabel(icon: "square.and.arrow.up")
                }
                .buttonStyle(.plain)
                .frame(width: metrics.controlSize, alignment: .trailing)
            } else {
                Color.clear
                    .frame(width: metrics.controlSize, height: metrics.controlSize)
            }
        }
        .padding(.horizontal, 10)
    }

    private func navigationStrip(metrics: FeedLayoutMetrics) -> some View {
        HStack(spacing: 14) {
            controlButton(icon: "arrow.up", metrics: metrics) {
                move(by: -1)
            }
            .disabled(currentIndex == 0)

            VStack(spacing: 4) {
                Text(normalizedGameName(from: currentGame.title))
                    .font(metrics.isCompactHeight ? .subheadline.weight(.heavy) : .headline.weight(.heavy))
                    .lineLimit(1)
            }
            .frame(maxWidth: .infinity)

import Foundation
import StoreKit
import SwiftUI

struct SkillGameGenerationRequest {
    var prompt: String
    var style: VisualStyle
    var difficulty: DifficultyTier
    var language: FlashPlayLanguage
    var userID: String
    var sessionToken: String?
}

struct FlashPlayUserSession: Codable, Equatable {
    enum Provider: String, Codable {
        case guest
        case apple
        case appleDemo = "apple-demo"
    }

    var userID: String
    var displayName: String
    var provider: Provider
    var sessionToken: String

    var isGuest: Bool {
        provider == .guest
    }
}

protocol GameGenerationSkillClient {
    var skillIdentifier: String { get }
    func generateGame(from request: SkillGameGenerationRequest) async throws -> GameItem
}

enum SkillGenerationError: LocalizedError {
    case emptyPrompt
    case invalidResponse
    case backendFailed(String)
    case httpError(Int)
    case insufficientCredits
    case generationInProgress

    var errorDescription: String? {
        switch self {
        case .emptyPrompt:
            return "Enter a gameplay description first."
        case .invalidResponse:
            return "Generation failed. Please try again."
        case .backendFailed(let message):
            return "Generation failed: \(message)"
        case .httpError(let statusCode):
            return "Generation request failed (HTTP \(statusCode))."
        case .insufficientCredits:
            return "Not enough tokens"
        case .generationInProgress:
            return "A generation task is already running"
        }
    }
}

enum BillingError: LocalizedError {
    case productUnavailable
    case purchasePending
    case purchaseCancelled
    case verificationFailed

    var errorDescription: String? {
        switch self {
        case .productUnavailable:
            return "充值暂不可用"
        case .purchasePending:
            return "支付处理中"
        case .purchaseCancelled:
            return "已取消支付"
        case .verificationFailed:
            return "支付校验失败"
        }
    }
}

struct FlashPlayGameSkillClient: GameGenerationSkillClient {
    var skillIdentifier: String {
        if SkillServiceConfig.backendBaseURL != nil {
            return "flashplay.backend.generation-gateway.v1"
        }
        return SkillServiceConfig.apiURL == nil
            ? "clawhub.ai/brianclan/aigames (fallback)"
            : "flashplay.skill.generate-game.v1"
    }
    private let backendClient = FlashPlayBackendGatewayClient()
    private let publishingClient = AIGamesPublishingSkillClient()
    private let fallbackClient = AIGamesRepositorySkillClient()
    private let localOpenClawClient = LocalOpenClawSkillClient()

    func generateGame(from request: SkillGameGenerationRequest) async throws -> GameItem {
        let cleanedPrompt = request.prompt.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanedPrompt.isEmpty else { throw SkillGenerationError.emptyPrompt }

        if SkillServiceConfig.backendBaseURL != nil {
            return try await backendClient.generateGame(from: request)
        }

        if SkillServiceConfig.localOpenClawURL != nil {
            do {
                let generated = try await localOpenClawClient.generateDraft(from: request)
                return try await publishingClient.generateGame(from: request, generated: generated)
            } catch {
                // Fall through to existing online/fallback chain.
            }
        }

        guard let apiURL = SkillServiceConfig.apiURL else {
            return try await generateViaAIGamesSkill(from: request)
        }

        var urlRequest = URLRequest(url: apiURL)
        urlRequest.httpMethod = "POST"
        urlRequest.setValue("application/json", forHTTPHeaderField: "Content-Type")
        if let token = SkillServiceConfig.bearerToken, !token.isEmpty {
            urlRequest.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        }

        let payload = SkillGeneratePayload(
            prompt: cleanedPrompt,
            style: request.style.rawValue,
            difficulty: request.difficulty.rawValue,
            language: request.language.generationCode
        )
        urlRequest.httpBody = try JSONEncoder().encode(payload)

        do {
            let (data, response) = try await URLSession.shared.data(for: urlRequest)
            guard let httpResponse = response as? HTTPURLResponse else {
                return try await generateViaAIGamesSkill(from: request)
            }
            guard (200...299).contains(httpResponse.statusCode) else {
                return try await generateViaAIGamesSkill(from: request)
            }

            let decoded = try JSONDecoder().decode(SkillGenerateResponse.self, from: data)
            guard let gameURLString = decoded.gameURL ?? decoded.url,
                  let normalizedURL = normalizeGameURL(gameURLString)
            else { return try await generateViaAIGamesSkill(from: request) }

            let title = decoded.title?.trimmingCharacters(in: .whitespacesAndNewlines)
            let summary = decoded.summary?.trimmingCharacters(in: .whitespacesAndNewlines)

            let mechanic = GameMechanic(rawValue: decoded.mechanic ?? "") ?? inferMechanic(from: cleanedPrompt)
            let genre = GameGenre(rawValue: decoded.genre ?? "") ?? inferGenre(from: mechanic)
            let style = VisualStyle(rawValue: decoded.style ?? "") ?? request.style
            let difficulty = DifficultyTier(rawValue: decoded.difficulty ?? "") ?? request.difficulty

            return GameItem(
                title: (title?.isEmpty == false ? title! : cleanedPrompt.components(separatedBy: "，").first ?? "新游戏"),
                summary: (summary?.isEmpty == false ? summary! : "由线上 Skill 生成，可直接在 App 内体验。"),
                creator: CreatorProfile(name: decoded.creatorName ?? "Skill Bot", badge: "AI 生成", followers: 0),
                mechanic: mechanic,
                genre: genre,
                style: style,
                difficulty: difficulty,
                likes: decoded.likes ?? Int.random(in: 200...900),
                comments: decoded.comments ?? Int.random(in: 18...90),
                shares: decoded.shares ?? Int.random(in: 8...66),
                playCount: decoded.playCount ?? Int.random(in: 500...2400),
                sessionLength: decoded.sessionLength ?? Int.random(in: 35...90),
                accent: [.orange, .pink, .mint, .yellow].randomElement() ?? .orange,
                background: [
                    Color(
                        red: Double.random(in: 0.2...1.0),
                        green: Double.random(in: 0.3...0.9),
                        blue: Double.random(in: 0.2...0.9)
                    ),
                    Color(
                        red: Double.random(in: 0.2...1.0),
                        green: Double.random(in: 0.3...0.9),
                        blue: Double.random(in: 0.2...0.9)
                    )
                ],
                onboardingTip: decoded.onboardingTip ?? "已接入线上 Skill 结果，点击即可体验小游戏。",
                externalGameURL: normalizedURL
            )
        } catch {
            return try await generateViaAIGamesSkill(from: request)
        }
    }

    private func inferMechanic(from prompt: String) -> GameMechanic {
        if prompt.contains("躲") || prompt.contains("避") { return .avoid }
        if prompt.contains("收") || prompt.contains("接") || prompt.contains("金币") || prompt.contains("鱼") { return .collect }
        if prompt.contains("泡") { return .bubble }
        return .tap
    }

    private func inferGenre(from mechanic: GameMechanic) -> GameGenre {
        switch mechanic {
        case .avoid: return .action
        case .collect: return .creative
        case .bubble: return .relaxing
        case .tap: return .puzzle
        }
    }

    private func normalizeGameURL(_ raw: String) -> URL? {
        guard let url = URL(string: raw.trimmingCharacters(in: .whitespacesAndNewlines)) else { return nil }
        return url
    }

    private func generateViaAIGamesSkill(from request: SkillGameGenerationRequest) async throws -> GameItem {
        do {
            return try await publishingClient.generateGame(from: request)
        } catch {
            return await fallbackClient.generateGame(from: request)
        }
    }
}

